#!/usr/bin/env python3
"""Apply curated translations for strings that should not fall back to English.

Run `npx prettier --write js/lib/i18n_catalogs/` from
`apps/retro_hex_chat_web/assets` afterwards. This writes the JS catalogs with
its own line breaks, and `make ci` checks them with prettier's — the gate goes
red on formatting alone if the pass is skipped.
"""

from __future__ import annotations

import argparse
import ast
import re
from pathlib import Path

from i18n_js_catalogs import LOCALE_EXPORTS, read_catalogs, write_catalogs
from i18n.locales import codes as enabled_locale_codes

PLACEHOLDER_RE = re.compile(r"%\{[A-Za-z0-9_]+\}")

DEFAULT_LOCALES = enabled_locale_codes()


def t(
    de: str,
    es: str,
    fr: str,
    id: str,
    ja: str,
    zh_hans: str,
    pt_BR: str | None = None,
    pt_PT: str | None = None,
    it: str | None = None,
    pl: str | None = None,
    nl: str | None = None,
    ru: str | None = None,
    zh_hant: str | None = None,
) -> dict[str, str]:
    translations = {
        "de": de,
        "es": es,
        "fr": fr,
        "id": id,
        "ja": ja,
        "zh_hans": zh_hans,
    }

    if pt_BR is not None:
        translations["pt_BR"] = pt_BR

    if pt_PT is not None:
        translations["pt_PT"] = pt_PT

    if it is not None:
        translations["it"] = it

    if pl is not None:
        translations["pl"] = pl

    if nl is not None:
        translations["nl"] = nl

    for locale, translated in {
        "ru": ru,
        "zh_hant": zh_hant,
    }.items():
        if translated is not None:
            translations[locale] = translated

    return translations


def source_t(source: str, translations: dict[str, str]) -> dict[str, str]:
    return {"en": source, **translations}


