            "Wähle Hex Pong, Light Trails, eine Star-Duel-Variante, eine Hex-Raid-Variante, eine Hex-Outlaw-Variante, eine Hex-Tennis-Variante, eine Hex-Invaders-Variante, eine Hex-Enduro-Variante, eine Hex-Skiing-Variante oder eine Hex-Hockey-Variante aus dem Retro-Spiele-Katalog.",
