            "在复古游戏单人模式中，你控制左侧坦克，AI 控制右侧坦克。难度会改变 AI 跟踪走廊、躲避导弹和开火的速度。",
            pt_BR="No modo solo de Jogos Retro, você controla o tanque esquerdo enquanto a IA controla o tanque direito. A dificuldade muda a rapidez da IA ao seguir corredores, desviar de mísseis e disparar.",
            pt_PT="No modo solo de Jogos Retro, controla o tanque esquerdo enquanto a IA controla o tanque direito. A dificuldade muda a rapidez da IA ao seguir corredores, desviar de mísseis e disparar.",
