            nl="In de solomodus van Retrogames bestuur je de linker tank terwijl de AI de rechter tank bestuurt. De moeilijkheid bepaalt hoe snel de AI gangen volgt, raketten ontwijkt en schiet.",
            ru="В соло-режиме ретро-игр вы управляете левым танком, а ИИ управляет правым. Сложность меняет скорость, с которой ИИ идет по коридорам, уклоняется от ракет и стреляет.",
            zh_hant="在復古遊戲單人模式中，你控制左側坦克，AI 控制右側坦克。難度會改變 AI 跟蹤走廊、躲避飛彈和開火的速度。",
