# Voice messages: the recording strip under the composer and the tile a
# recording gets. Curated because almost every string here is a one- or
# two-word control ("Record", "Attach") that a model reads as the other sense
# of the word — the merge guessed "Attach" as "Attack" in every locale — and
# because the prose has to say where recording is offered without sounding like
# something is missing everywhere else.
