# The arcade HUD. Machine translation left this vocabulary in three states and
# none of them shippable: still English, half English ("TODOS LOS BLOCKS
# CLEARED"), or invented ("AVALANCHE CESAP", "EARTH INVED", "ZACZYSZCZONE").
# One locale shipped the internal colour sentinels of the renderer inside the
# string. These are two-word scoreboard shouts with no sentence around them —
# the same reason `i18n/glossary.py` exists for buttons — so they are curated
# here, in full, rather than filled per missing locale.
